<template><el-drawer v-model="visible" size="78%" class="result-drawer"><template #header><div><h2>执行结果 · {{process?.scenarioName}}</h2><span class="muted">{{run?.runId}} · {{process?.currentStep}}</span></div></template><div v-loading="loading"><div class="result-metrics"><el-statistic title="数据总数" :value="run?.businessSummary?.totalRows||0"/><el-statistic title="成功" :value="run?.businessSummary?.passedRows||0"><template #suffix><el-icon color="#20a66a"><CircleCheck/></el-icon></template></el-statistic><el-statistic title="失败" :value="run?.businessSummary?.failedRows||0"><template #suffix><el-icon color="#e05252"><CircleClose/></el-icon></template></el-statistic><el-statistic title="执行状态" :value="statusText"/></div><div class="evidence-layout"><el-card><template #header><strong>执行步骤</strong></template><el-timeline><el-timeline-item v-for="item in process?.steps||[]" :key="item.name" :type="item.status==='passed'?'success':item.status==='failed'?'danger':'primary'" :timestamp="item.updatedAt"><strong>{{item.name}}</strong><p>{{item.message}}</p></el-timeline-item></el-timeline></el-card><el-card><template #header><div class="card-header"><strong>截图与录像</strong><div><el-button v-if="process?.videoReplayUrl" link type="primary" @click="asset=process.videoReplayUrl">录像回放</el-button><el-button v-if="reportUrl" link type="primary" @click="window.open(reportUrl)">HTML 报告</el-button></div></div></template><div class="evidence-stage"><iframe v-if="asset?.includes('replay')" :src="asset"/><el-image v-else-if="asset" :src="asset" fit="contain" :preview-src-list="[asset]"/><el-empty v-else description="本次执行暂无截图或录像"/></div><div class="asset-strip"><button v-for="item in process?.evidence||[]" :key="item.url" @click="asset=item.previewUrl||item.url"><el-image v-if="item.type==='screenshot'" :src="item.previewUrl||item.url" fit="cover"/><el-icon v-else><VideoPlay/></el-icon><span>{{item.label}}</span></button></div></el-card></div></div></el-drawer></template>
<script setup>import{computed,ref}from'vue';import{CircleCheck,CircleClose,VideoPlay}from'@element-plus/icons-vue';import{api}from'../api';const visible=ref(false),run=ref(),process=ref(),loading=ref(false),asset=ref('');const statusText=computed(()=>({passed:'通过',failed:'失败',running:'执行中',queued:'排队中'})[run.value?.status]||run.value?.status),reportUrl=computed(()=>process.value?.artifacts?.find(a=>a.type==='html-report')?.url);async function open(item){run.value=item;visible.value=true;loading.value=true;try{process.value=await api(`/api/runs/${item.runId}/process`);asset.value=process.value.latestScreenshotUrl||process.value.videoReplayUrl||''}finally{loading.value=false}}defineExpose({open})</script>
